const bizSdk = require('facebook-nodejs-business-sdk');

const EventRequest = bizSdk.EventRequest;
const ServerEvent = bizSdk.ServerEvent;

const accessToken = 'ВАШ_ACCESS_TOKEN';
const pixelId = 'ВАШ_PIXEL_ID';

const event = new ServerEvent()
  .setEventName('Purchase')
  .setEventTime(Math.floor(new Date() / 1000))
  .setUserData({ email: 'user@mail.com' })
  .setCustomData({ currency: 'USD', value: 55.00 });

const eventRequest = new EventRequest(
  accessToken,
  pixelId
).setEvents([event]);

eventRequest.execute()
  .then(res => console.log('Подію відправлено:', res))
  .catch(err => console.error('Помилка відправки:', err));

